INSERT INTO sentences (id, language_id, text, reading_kana, level_id, source, published) VALUES
INSERT INTO sentence_translations (id, sentence_id, lang, text, source) VALUES
  ('st-ex-sarukoto-1', 'sent-ex-sarukoto-1', 'en', 'The taste aside, it is cheap as well.', 'authored'),
  ('st-ex-sarukoto-2', 'sent-ex-sarukoto-2', 'en', 'Talent aside, it is effort that matters.', 'authored'),
  ('st-ex-sarukoto-3', 'sent-ex-sarukoto-3', 'en', 'The design aside, it is easy to use.', 'authored'),
  ('st-ex-sarukoto-4', 'sent-ex-sarukoto-4', 'en', 'Experience aside, character is what counts.', 'authored'),
  ('st-ex-nishite-1', 'sent-ex-nishite-1', 'en', 'It is something only he could do.', 'authored'),
  ('st-ex-nishite-2', 'sent-ex-nishite-2', 'en', 'Looking back on it now, it was a mistake.', 'authored'),
  ('st-ex-nishite-3', 'sent-ex-nishite-3', 'en', 'The town changed in a single day.', 'authored'),
  ('st-ex-nishite-4', 'sent-ex-nishite-4', 'en', 'It is a problem even a teacher cannot solve.', 'authored'),
  ('st-ex-omoikiya-1', 'sent-ex-omoikiya-1', 'en', 'I thought it would clear up, and instead it rained.', 'authored'),
  ('st-ex-omoikiya-2', 'sent-ex-omoikiya-2', 'en', 'I thought it would be simple, and it took ages.', 'authored'),
  ('st-ex-omoikiya-3', 'sent-ex-omoikiya-3', 'en', 'I thought he would not come, and there he was.', 'authored'),
  ('st-ex-omoikiya-4', 'sent-ex-omoikiya-4', 'en', 'I thought it was cheap, and it was expensive.', 'authored'),
  ('st-ex-niarazu-1', 'sent-ex-niarazu-1', 'en', 'This is no joke.', 'authored'),
  ('st-ex-niarazu-2', 'sent-ex-niarazu-2', 'en', 'He is no ordinary man.', 'authored'),
  ('st-ex-niarazu-3', 'sent-ex-niarazu-3', 'en', 'Success is no accident.', 'authored'),
  ('st-ex-niarazu-4', 'sent-ex-niarazu-4', 'en', 'This is no dream.', 'authored'),
  ('st-ex-bakoso-1', 'sent-ex-bakoso-1', 'en', 'It is precisely because you work at it that you succeed.', 'authored'),
  ('st-ex-bakoso-2', 'sent-ex-bakoso-2', 'en', 'It is because I care that I speak sharply.', 'authored'),
  ('st-ex-bakoso-3', 'sent-ex-bakoso-3', 'en', 'It is only because I am in good health that I can work.', 'authored'),
  ('st-ex-bakoso-4', 'sent-ex-bakoso-4', 'en', 'It is thanks to him alone that this company exists.', 'authored'),
  ('st-ex-deare-1', 'sent-ex-deare-1', 'en', 'Child or adult, the rules are the same.', 'authored'),
  ('st-ex-deare-2', 'sent-ex-deare-2', 'en', 'Whatever the reason, being late is a nuisance.', 'authored'),
  ('st-ex-deare-3', 'sent-ex-deare-3', 'en', 'Even a teacher makes mistakes.', 'authored'),
  ('st-ex-deare-4', 'sent-ex-deare-4', 'en', 'Rain or snow, I am going.', 'authored'),
  ('st-ex-narinari-1', 'sent-ex-narinari-1', 'en', 'Ring me or write to me — get in touch somehow.', 'authored'),
  ('st-ex-narinari-2', 'sent-ex-narinari-2', 'en', 'Read a book, listen to music, do as you please.', 'authored'),
  ('st-ex-narinari-3', 'sent-ex-narinari-3', 'en', 'Meat or fish — take whichever you like.', 'authored'),
  ('st-ex-narinari-4', 'sent-ex-narinari-4', 'en', 'Talk to a teacher, or your parents, or somebody.', 'authored'),
  ('st-ex-dano-1', 'sent-ex-dano-1', 'en', 'Too hot, too cold — nothing but complaints.', 'authored'),
  ('st-ex-dano-2', 'sent-ex-dano-2', 'en', 'Meat and fish and the rest of it — I bought the lot.', 'authored'),
  ('st-ex-dano-3', 'sent-ex-dano-3', 'en', 'Busy, tired — he is full of excuses.', 'authored'),
  ('st-ex-dano-4', 'sent-ex-dano-4', 'en', 'Books and notebooks and what have you are all over the desk.', 'authored'),
  ('st-ex-tsutsutsu-1', 'sent-ex-tsutsutsu-1', 'en', 'He is pacing up and down the room.', 'authored'),
  ('st-ex-tsutsutsu-2', 'sent-ex-tsutsutsu-2', 'en', 'Going back and forth over it, I worked out the answer.', 'authored'),
  ('st-ex-tsutsutsu-3', 'sent-ex-tsutsutsu-3', 'en', 'It is a give-and-take relationship.', 'authored'),
  ('st-ex-tsutsutsu-4', 'sent-ex-tsutsutsu-4', 'en', 'People live by give and take.', 'authored'),
  ('st-ex-kotonaku-1', 'sent-ex-kotonaku-1', 'en', 'He worked without a break.', 'authored'),
  ('st-ex-kotonaku-2', 'sent-ex-kotonaku-2', 'en', 'He kept at it without giving up.', 'authored'),
  ('st-ex-kotonaku-3', 'sent-ex-kotonaku-3', 'en', 'It is unchanged, just as it was.', 'authored'),
  ('st-ex-kotonaku-4', 'sent-ex-kotonaku-4', 'en', 'He decided without a moment’s hesitation.', 'authored')
